function UserList() {
  const [users, setUsers] = useState([]);
  useEffect(() => {
    const conn = mysql.createConnection({
      host: 'localhost',
      user: 'root',
      database: 'test'
    });
    conn.query('SELECT * FROM users', (err, results) => {
      setUsers(results);
    });
  }, []);
  return <ul>{users.map(u => <li>{u.name}</li>)}</ul>;
}

